/// <reference types="vitest/config" />
import { fileURLToPath } from 'node:url'
import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import wails from '@wailsio/runtime/plugins/vite'

export default defineConfig(({ mode }) => ({
  server: {
    host: '127.0.0.1',
    port: Number(process.env.WAILS_VITE_PORT) || 9245,
    strictPort: true,
  },
  // Wails bindings are generated by the Go toolchain and are not needed in unit tests.
  plugins: [react(), mode !== 'test' && wails('./bindings')],
  test: {
    environment: 'jsdom',
    setupFiles: ['./src/test/setup.ts'],
    // Primer ships CSS modules; class names are not needed in tests.
    css: false,
    // Primer imports its CSS from JavaScript, which Node cannot load.
    server: { deps: { inline: [/@primer\/react/] } },
    // Its Node entry defines <live-region> on a server shim instead of the
    // jsdom window, so SelectPanel announcements would fail.
    alias: {
      '@primer/live-region-element': fileURLToPath(
        new URL('node_modules/@primer/live-region-element/dist/esm/index.js', import.meta.url),
      ),
    },
  },
}))
